<template><div><h2>运营数据首页</h2><el-row :gutter="16" v-loading="loading"><el-col v-for="card in cards" :key="card.label" :span="4"><el-card><div class="metric-label">{{card.label}}</div><div class="metric">{{card.value}}</div></el-card></el-col></el-row><el-card class="panel"><template #header>路网实时状态</template><div ref="chart" class="chart"></div></el-card></div></template>
<script setup lang="ts">import {onMounted, ref} from 'vue'; import * as echarts from 'echarts'; import {api} from '../../api'; const loading=ref(true); const chart=ref<HTMLElement>(); const cards=ref([{label:'平均速度',value:'--'},{label:'平均延误',value:'--'},{label:'拥堵指数',value:'--'},{label:'在线设备',value:'--'},{label:'活跃事件',value:'--'}]); onMounted(async()=>{try{const {data}=await api.summary(); const x=data.data; cards.value=[{label:'平均速度',value:`${x.averageSpeed.toFixed(1)} km/h`},{label:'平均延误',value:`${x.averageDelay.toFixed(1)} s`},{label:'拥堵指数',value:x.congestionIndex.toFixed(2)},{label:'在线设备',value:`${x.onlineDevices}/${x.deviceTotal}`},{label:'活跃事件',value:String(x.activeEvents)}]}finally{loading.value=false} if(chart.value){const c=echarts.init(chart.value); c.setOption({tooltip:{trigger:'axis'},xAxis:{type:'category',data:['06:00','08:00','10:00','12:00','14:00','16:00','18:00']},yAxis:{type:'value'},series:[{name:'拥堵指数',type:'line',smooth:true,data:[1.1,2.4,1.8,1.5,1.9,2.7,2.1]}]})}})</script>
